// TestNearbyRiders is the resolver for the testNearbyRiders field.
func (r *queryResolver) TestNearbyRiders(ctx context.Context, center model.CoordinateInput, riders []*model.CoordinateInput) ([]*model.NearbyRider, error) {
	var closest *model.NearbyRider
	minDistance := math.MaxFloat64

	for _, rider := range riders {
		dist := tracking.Haversine(center.Lat, center.Lng, rider.Lat, rider.Lng)

		if dist < minDistance {
			minDistance = dist
			closest = &model.NearbyRider{
				Name:     rider.Name,
				Lat:      rider.Lat,
				Lng:      rider.Lng,
				Distance: dist,
			}
		}
	}

	if closest != nil {
		return []*model.NearbyRider{closest}, nil
	}

	// In case no riders were passed in
	return []*model.NearbyRider{}, nil
}

